def _es_de_la_maquina(texto):
    """True si el texto lo escribio la maquina, no Julio.

    Se descarta lo que venga de un pedido a un cerebro o de un expediente:
    lo que empiece por 'Eres el', lo que pida contestar en JSON, lo que sea
    una linea de un JSON (empieza por comillas y lleva dos puntos), y lo que
    traiga dentro las palabras OBRERO, AUDITOR, VEREDICTO o GUARDIA.
    """
    t = (texto or "").strip()
    if not t:
        return True
    if t.startswith("Eres el"):
        return True
    if "JSON" in t or "json" in t:
        return True
    if t.startswith('"') and ":" in t:
        return True
    for marca in ("OBRERO", "AUDITOR", "VEREDICTO", "GUARDIA"):
        if marca in t:
            return True
    return False


